import{_ as o,C as a,o as n,c as r,j as t,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse(`{"title":"CI runs in your editor","description":"Follow a Playwright CI run of your branch from VS Code or a JetBrains IDE while it runs: its tests and progress, the line each running test is at, and its pages from the team instance's live view, watched only but for Pause, Resume, End the test and Let it go, for those who may control it.","frontmatter":{"title":"CI runs in your editor","description":"Follow a Playwright CI run of your branch from VS Code or a JetBrains IDE while it runs: its tests and progress, the line each running test is at, and its pages from the team instance's live view, watched only but for Pause, Resume, End the test and Let it go, for those who may control it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-ci-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-ci-runs.html"}],["meta",{"property":"og:title","content":"CI runs in your editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Follow a Playwright CI run of your branch from VS Code or a JetBrains IDE while it runs: its tests and progress, the line each running test is at, and its pages from the team instance's live view, watched only but for Pause, Resume, End the test and Let it go, for those who may control it."}]]},"headers":[],"relativePath":"features/editor-ci-runs.md","filePath":"features/editor-ci-runs.md","lastUpdated":1795619799000}`),u={name:"features/editor-ci-runs.md"};function d(c,e,w,p,f,g){const s=a("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"ci-runs-in-your-editor",tabindex:"-1"},[i("CI runs in your editor "),t("a",{class:"header-anchor",href:"#ci-runs-in-your-editor","aria-label":'Permalink to "CI runs in your editor"'},"​")],-1)),h(s,{editor:""}),e[1]||(e[1]=l('<p>While CI runs your branch, the <a href="./editors.html">editor extensions</a> show that run beside your own: its progress, its tests as they end, the line each running test is at, and, when its project has the <a href="./live-view.html">live view</a> on, its pages. It is watched only, but for the controls offered to the people who may control the run: <strong>Let it go</strong> on a test the project <a href="./hold-ci-failure.html">holds at its failure</a>, and <strong>Pause</strong>, <strong>Resume</strong> and <strong>End the test</strong> when the project lets them <a href="./pause-ci-test.html">pause a CI test</a>. Nothing else steps, holds or shares a CI run from the editor.</p><h2 id="which-runs" tabindex="-1">Which runs <a class="header-anchor" href="#which-runs" aria-label="Permalink to &quot;Which runs&quot;">​</a></h2><p>A CI run of the branch your workspace reads or has checked out, or a teammate&#39;s on it or on the branch your results are <a href="./editor-status-bar.html#compare-with-another-run">compared with</a>, shows while it runs. The editor finds it as the instance announces it, or as it reads the latest run of the branch in progress. It follows the two newest runs of a branch at most, and stops following a run as it ends, as a newer run takes its place, or when the workspace reads another instance, project or branch.</p><p>VS Code&#39;s status bar says <code>CI run #125</code> or <code>run #126</code>, and its Testing view <code>Piwi: CI run #125 on main</code>, with results as they end; your own run keeps the status bar. A test line Piwi marks keeps its own latest result, and its hover names the CI run running it.</p><h2 id="the-ci-run-s-tests" tabindex="-1">The CI run&#39;s tests <a class="header-anchor" href="#the-ci-run-s-tests" aria-label="Permalink to &quot;The CI run&#39;s tests&quot;">​</a></h2><ul><li><strong>The CI Runs view</strong> of VS Code&#39;s Piwi panel, and the <strong>CI run</strong> tab of the JetBrains Piwi tool window, show while a CI run runs. Each lists <code>CI run #78</code>, its branch and progress, <strong>Open run #78</strong> and its tests: those running, then the latest that ended, failures first. A running test opens the call it is at, else its spec (a double click in JetBrains).</li><li><strong>The line each running test is at</strong> ends with a plain mark in the CodeLens or inlay color, <code>CI run #78 · worker 2: Click getByRole(&#39;button&#39;)</code>: a <a href="/guide/concepts.html#ci-position">CI position</a>, never a stop, on the line of the run&#39;s commit. It shows in a file of your workspace only, placed from the run&#39;s own steps: never one in <code>node_modules</code> or outside the workspace.</li><li><strong>Piwi Picker&#39;s Runs window</strong> lists them too: <a href="./runs-window.html#open-it">CI runs</a>.</li></ul><h2 id="watch-a-ci-lane" tabindex="-1">Watch a CI lane <a class="header-anchor" href="#watch-a-ci-lane" aria-label="Permalink to &quot;Watch a CI lane&quot;">​</a></h2><p><strong>Watch</strong>, under a running test whose project has the <a href="./live-view.html">live view</a> on, opens its lane read-only, named <code>CI run #78 · worker 2</code>, in the VS Code worker panel, the JetBrains <strong>Worker</strong> tab or the Runs window: no <strong>Interact</strong>, no pick. It follows the lane through its next tests, and ends with the run, as you hide or close the view, or as the instance closes it, saying why. Its images come from the <a href="./live-view.html#what-is-sent-to-whom-and-what-is-kept">team instance</a>, read with the editor&#39;s connection; under the image, the same layers as a local lane (<a href="./watch-running-test.html#beside-the-image">Beside the image</a>).</p><p><strong>Watch on the dashboard</strong> opens the lane on the run&#39;s page, offered where the editor cannot show it (an older instance, a refused <strong>Watch</strong>).</p><h3 id="a-failure-held-for-you" tabindex="-1">A failure held for you <a class="header-anchor" href="#a-failure-held-for-you" aria-label="Permalink to &quot;A failure held for you&quot;">​</a></h3><p>When the project <a href="./hold-ci-failure.html">holds a failing CI test</a> for its controllers and your editor&#39;s connection may control the project&#39;s runs (its key is a Maintainer&#39;s or a Project admin&#39;s), your watch of a lane counts: a test that fails in it waits at its failure, as it would for the run page. The worker panel or the <strong>Worker</strong> tab then says <strong>Failed, held at its line · Held for Ana · until 12:05</strong>, the error, its place (which opens the failing line), and that the CI job&#39;s own timeout still runs; the CI Runs list marks the test <strong>Failed, held at its line</strong>. <strong>Let it go</strong> ends the wait, once: the test tears down as it would have, its result unchanged.</p><p><strong>Let it go</strong> goes on your watch of that lane, so it shows only while you watch it, and only once the instance has said your connection may control the run. The Runs window does the same with its own connection (<a href="./hold-ci-failure.html#where-it-shows">Where it shows</a>). Anyone else watching sees the hold without it. A refusal is said in the instance&#39;s words, under the caption.</p><h3 id="a-test-paused-for-you" tabindex="-1">A test paused for you <a class="header-anchor" href="#a-test-paused-for-you" aria-label="Permalink to &quot;A test paused for you&quot;">​</a></h3><p>When the project also lets its controllers <a href="./pause-ci-test.html">pause a CI test</a>, the same watch offers <strong>Pause</strong> while the lane&#39;s test runs. Until the test stops before its next call, the panel or tab says <strong>Pause asked by Ana</strong>, and <strong>Resume</strong> takes the Pause back; one the worker dropped says why. Paused, it says <strong>Paused by Ana · until 12:05</strong>, the call it stopped before and its place, and the job&#39;s timeout note, with <strong>Resume</strong> and <strong>End the test</strong>; the CI Runs list marks it <strong>Paused</strong>. Each button is asked once in each state of the lane, its refusal in the instance&#39;s words.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Watched only, but Pause, Resume, End the test and Let it go, for those who may control it.</strong> No other control, share or hold reaches a CI run, and its position is never a stop.</li><li><strong>One worker per editor.</strong> The worker panel or tab watches one lane, a local worker&#39;s or a CI run&#39;s: watching another moves it there.</li><li><strong>A run&#39;s steps.</strong> The positions come from the steps the CI run&#39;s reporter streams, so a run whose reporter streams none lists its tests without them.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./watch-running-test.html">Watch a local test</a>: a test running on your machine.</li><li><a href="./live-view.html">Live view of a run</a>: the team instance&#39;s view of a run, which a CI lane comes from.</li><li><a href="./editor-failures.html">Failures in the editor</a>: the CI run&#39;s failures once it ended.</li></ul>',18))])}const b=o(u,[["render",d]]);export{y as __pageData,b as default};
